# Things in the catalogue the book deliberately does not introduce, each with
# the reason. A pattern and a reason, so the coverage rule can say what was
# excused and why rather than silently counting it as done.
EXCUSED = [
    (r"^elysiumwilds:vale_portal$", "the gate a ring of Vale Frames lights: walked into, never held or placed"),
    (r"^elysiumagronomy:.*_spawn_egg$", "spawn eggs are creative-only"),
    (r"^elysiumspace:.*_spawn_egg$", "spawn eggs are creative-only"),
    (r"^elysiumspace:(oil|fuel|diesel)$", "fluid blocks: met as a lake or a spill, and carried as the bucket the book introduces"),
    (r"^elysiumspace:rime_spit$", "a projectile the hollow moonfolk throws, not a creature; introduced in the moonfolk quest"),
    (r"^elysiumwilds:biome_compass_\d\d$", "sprite-only needle frames of the surveyor's compass, never an item in hand"),
    (r"^elysium:.*_spawn_egg$", "spawn eggs are creative-only"),
    (r"^elysiumnpcs:envoy$", "met, not hunted: the envoy is introduced by the pages about its arrival and its ledger, and a guide that asked for one dead would be steering a player against the Empire"),
    (r"^elysiumcolonies:(settlement_seed|ruin_seed)$", "the survey stake and the ruin marker have no item and no recipe, are placed by the world, and are spent on their first random tick when a player comes near, so nobody ever holds or touches one; the_town explains both in its first two pages"),
    (r"^elysiumbestiary:.*_spawn_egg$", "spawn eggs are creative-only; every creature is introduced by slay"),
    (r"^elysiummobs:.*_spawn_egg$", "spawn eggs are creative-only; every family is introduced by slay"),
    (r"^elysiumarsenal:.*_pulling_[0-2]$", "pulling-state bow sprites, registered only so a drawn bow renders"),
    (r"^elysiumbestiary:bolt$", "the relic bolt is the projectile an arcana relic's ability throws, not a creature met"),
    (r"^elysiumbestiary:shade$", "the shade is the player's own summon from an arcana relic ability, gone in 600 ticks"),
    (r"^elysiumcomforts:.*_spawn_egg$", "spawn eggs are creative-only"),
    (r"^elysiumcomforts:(charred_)?pigeon$", "no natural spawn, recipe or breeding stock reaches a survival player yet (the only source is the creative spawn egg), and a creature can only be named by slay, which is no way to meet a courier; the pigeonhole quest's words carry them"),
]


def catalogue():
    """The pack's catalogue of what every module adds, by kind."""
    if not os.path.isfile(CATALOGUE):
        return {}
    return json.load(open(CATALOGUE, encoding="utf-8"))


def kinds_of(ids):
    """Which registry each catalogued id belongs to: block, item or creature."""
    found = {}
    for entry in catalogue().values():
        for kind, key in (("Blocks", "block"), ("Items", "item"), ("Creatures", "creature")):
            for row in entry.get("kinds", {}).get(kind, []):
                full = qualified(entry, row[0])
                if full in ids and full not in found:
                    found[full] = key
    return found


def qualified(entry, path):
    """A catalogue row's id with its module's namespace; the catalogue writes paths."""
    return path if ":" in path else f"{entry['modid']}:{path}"


def worlds():
    """Every dimension the catalogue knows, plus the base game's three."""
    known = set(WORLDS)
    for entry in catalogue().values():
        for row in entry.get("kinds", {}).get("Dimensions", []):
            known.add(qualified(entry, row[0]))
    return sorted(known)


def world_name(world):
    if world in WORLDS:
        return WORLDS[world]
    return world.split(":", 1)[1].replace("_", " ").title()


def language(quests, chapters):
    entries = dict(LINES)
    for world in worlds():
        entries[f"{NS}.world.{world.replace(':', '.')}"] = world_name(world)
    for chapter in chapters:
        title, why = CHAPTERS[chapter]
        entries[f"{NS}.chapter.{chapter}"] = title
        entries[f"{NS}.why.chapter.{chapter}"] = why
    for quest in quests:
        title, why = QUESTS[quest]
        entries[f"{NS}.quest.{quest}"] = title
        entries[f"{NS}.why.{quest}"] = why
    write(os.path.join(ASSETS, "lang/en_us.json"), dict(sorted(entries.items())))
    return len(entries)


# ---------------------------------------------------------------------------
# The one sprite and the one recipe
# ---------------------------------------------------------------------------

CLEAR = (0, 0, 0, 0)
COVER = [(46, 34, 58), (74, 56, 92), (108, 84, 132), (150, 124, 176)]
PAGE = [(196, 188, 168), (222, 216, 198), (240, 236, 224), (252, 250, 244)]
MARK = (127, 112, 196)


def rgba(colour):
    return (colour[0], colour[1], colour[2], 255)


def book():
    image = Image.new("RGBA", (16, 16), CLEAR)
    draw = ImageDraw.Draw(image)
    draw.rectangle([2, 2, 13, 13], fill=rgba(COVER[1]), outline=rgba(COVER[0]))
    draw.rectangle([4, 3, 12, 12], fill=rgba(PAGE[2]), outline=rgba(PAGE[0]))
    draw.line([(3, 2), (3, 13)], fill=rgba(COVER[3]))
    for y in (5, 7, 9):
        draw.line([(6, y), (10, y)], fill=rgba(PAGE[0]))
    draw.line([(11, 1), (11, 6)], fill=rgba(MARK))
    return image


def tags():
    """One tag file per family and registry, every entry optional."""
    made = 0
    every = set()
    for ids in FAMILIES.values():
        every.update(ids)
    registry = kinds_of(every)
    for family, ids in sorted(FAMILIES.items()):
        by = {"item": [], "block": [], "entity_type": []}
        for one in ids:
            kind = registry.get(one)
            if kind == "block":
                by["block"].append(one)
                by["item"].append(one)
            elif kind == "creature":
                by["entity_type"].append(one)
            else:
                by["item"].append(one)
        for folder, members in by.items():
            if not members:
                continue
            write(os.path.join(DATA, "tags", folder, family + ".json"), {
                "replace": False,
                "values": [{"id": one, "required": False} for one in members],
            })
            made += 1
    return made


def files(quests, chapters):
    os.makedirs(os.path.join(ASSETS, "textures/item"), exist_ok=True)
    book().save(os.path.join(ASSETS, "textures/item/almanac.png"))
    write(os.path.join(ASSETS, "models/item/almanac.json"),
          {"parent": "item/generated", "textures": {"layer0": f"{NS}:item/almanac"}})
    write(os.path.join(DATA, "recipe/almanac.json"), {
        "type": "minecraft:crafting_shapeless",
        "category": "misc",
        "ingredients": [{"item": "minecraft:book"}, {"item": "minecraft:feather"}],
        "result": {"id": f"{NS}:almanac", "count": 1},
    })
    return 3 + tags()


if __name__ == "__main__":
    quests, chapters = ids()
    missing = [q for q in quests if q not in QUESTS]
    spare = [q for q in QUESTS if q not in quests]
    if missing or spare:
        print(f"the words and the graph disagree: {missing} have no words and {spare} "
              f"are words for nothing")
        sys.exit(1)
    made = files(quests, chapters)
    keys = language(quests, chapters)
    print(f"almanac: {len(chapters)} chapter(s), {len(quests)} quest(s), {len(FAMILIES)} "
          f"famil(ies), {made} file(s), {keys} language key(s)")
